/* From Uiverse.io by lonefox-xxx - Tags: card */
.__UIV_SCOPE__ .card {
  width: 210px;
  height: 235px;
  background: #212121;
  box-shadow: rgba(0, 0, 0, 0.4) 10px 20px 30px, rgba(0, 0, 0, 0.3) 10px 1px 53px 3px, rgba(1, 0, 0, 0.2) 0px -1px 3px inset;
  text-align: center;
  cursor: pointer;
  transition: all 0.5s;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
  font-weight: bolder;
  color: #fff;
}

.__UIV_SCOPE__ .card:hover {
  transform: scale(1.021);
}

.__UIV_SCOPE__ .card:active {
  transform: scale(0.95) rotateZ(1.1deg);
}
